package com.bananalab.lite;
import android.content.*;import org.json.*;import java.util.*;import java.util.regex.*;
/** Versioned local code data, test-before-activation and recoverable hot updates. */
final class RuntimeModules{
 static final String EMPTY="{\"version\":1,\"modules\":[]}";
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-runtime-modules",0);}
 static String code(Context c){return prefs(c).getString("active",EMPTY);}
 static int revision(Context c){return prefs(c).getInt("revision",0);}
 static void commit(SharedPreferences.Editor e)throws Exception{if(!e.commit())throw new java.io.IOException("No pude guardar el cambio del taller; se conserva la revisión anterior.");}
 static synchronized void stage(Context c,String raw,int base)throws Exception{if(revision(c)!=base)throw new IllegalArgumentException("La revisión cambió mientras editabas. Volvé a abrir el código actual.");RuntimeProgram program=new RuntimeProgram(raw);commit(prefs(c).edit().putString("candidate",program.source.toString()).putInt("candidateBase",base).remove("candidateReport"));}
 static String candidate(Context c){return prefs(c).getString("candidate","");}
 static synchronized String testCandidate(Context c)throws Exception{String raw=candidate(c);if(raw.isEmpty())return "No hay un borrador de código. Prepará el ejemplo, usá reparar este pedido o abrí el editor.";if(prefs(c).getInt("candidateBase",-1)!=revision(c))throw new IllegalArgumentException("El borrador corresponde a otra revisión.");String report=new RuntimeProgram(raw).test();commit(prefs(c).edit().putString("candidateReport",report));return report;}
 static JSONArray history(Context c)throws Exception{return new JSONArray(prefs(c).getString("history","[]"));}
 static JSONArray push(JSONArray old,JSONObject row)throws Exception{JSONArray next=new JSONArray();for(int i=Math.max(0,old.length()-4);i<old.length();i++)next.put(old.getJSONObject(i));next.put(row);return next;}
 static synchronized String activate(Context c)throws Exception{String raw=candidate(c);if(raw.isEmpty())return "No hay un borrador de código para activar.";int base=prefs(c).getInt("candidateBase",-1);if(base!=revision(c))throw new IllegalArgumentException("El código activo cambió; prepará el borrador otra vez.");RuntimeProgram p=new RuntimeProgram(raw);String report=p.test();JSONArray past=push(history(c),new JSONObject().put("code",code(c)).put("revision",base));commit(prefs(c).edit().putString("history",past.toString()).putString("active",p.source.toString()).putInt("revision",base+1).putString("report",report).putString("event","Activación local comprobada").remove("candidate").remove("candidateBase").remove("candidateReport"));return "Revisión "+(base+1)+" activada en esta misma instalación. El próximo pedido ya usa este código de comportamiento.\n"+report;}
 static synchronized String rollback(Context c)throws Exception{JSONArray past=history(c);if(past.length()==0)return "No hay una revisión anterior del taller.";JSONObject row=past.getJSONObject(past.length()-1);RuntimeProgram restored=new RuntimeProgram(row.getString("code"));String report=restored.test();JSONArray kept=new JSONArray();for(int i=0;i<past.length()-1;i++)kept.put(past.getJSONObject(i));int version=revision(c)+1;commit(prefs(c).edit().putString("active",restored.source.toString()).putInt("revision",version).putString("history",kept.toString()).putString("report",report).putString("event","Recuperado código de revisión "+row.optInt("revision")).putString("discarded",code(c)).remove("candidate").remove("candidateBase").remove("candidateReport"));return "Recuperé el código de la revisión "+row.optInt("revision")+" como revisión activa "+version+". No modifiqué tu escena; las animaciones ya creadas se conservan.";}
 static synchronized String recover(Context c)throws Exception{try{if(history(c).length()>0)return rollback(c);}catch(Exception invalidBackup){}commit(prefs(c).edit().putString("discarded",code(c)).putString("active",EMPTY).putInt("revision",revision(c)+1).putString("history","[]").putString("event","Recuperación automática al motor base").remove("candidate").remove("candidateBase"));return "Desactivé el código defectuoso y recuperé el motor base.";}
 static synchronized void log(Context c,String request,String detail)throws Exception{String q=request.substring(0,Math.min(240,request.length()));commit(prefs(c).edit().putString("lastRequest",q).putString("lastDiagnostic",detail.substring(0,Math.min(2000,detail.length()))).putLong("lastDiagnosticAt",System.currentTimeMillis()));}
 static JSONObject step(String op,String who,String to)throws Exception{JSONObject o=new JSONObject().put("op",op).put("who",who);if(!to.isEmpty())o.put("to",to);return o;}
 static JSONObject module(String id,String pattern,JSONArray steps,JSONArray expected)throws Exception{String sample=pattern.replace("{actor}","Fito").replace("{target}","Bani");return new JSONObject().put("id",id).put("pattern",pattern).put("steps",steps).put("tests",new JSONArray().put(new JSONObject().put("input",sample).put("actions",expected)));}
 static JSONObject example()throws Exception{return module("celebracion","{actor} celebra con {target}",new JSONArray().put(step("baila","actor","")).put(step("saluda","target","")).put(step("salta","actor","")),new JSONArray().put("baila").put("saluda").put("salta"));}
 static synchronized void upsert(Context c,JSONObject module)throws Exception{JSONObject root=new JSONObject(code(c));JSONArray old=root.getJSONArray("modules"),next=new JSONArray();for(int i=0;i<old.length();i++)if(!old.getJSONObject(i).getString("id").equals(module.getString("id")))next.put(old.getJSONObject(i));next.put(module);root.put("modules",next);stage(c,root.toString(),revision(c));}
 static String status(Context c)throws Exception{return "Taller de módulos · revisión "+revision(c)+"\nMódulos activos: "+new RuntimeProgram(code(c)).modules.size()+" / 16\nReparación automática acotada: "+(prefs(c).getBoolean("autoRepair",true)?"activada":"pausada")+"\nBorrador: "+(candidate(c).isEmpty()?"ninguno":"guardado")+"\nCódigo: lenguaje JSON de comportamientos, interpretado en Android. No modifica el APK Java ni los pesos.\n\nÚltimo cambio: "+prefs(c).getString("event","versión base")+"\n"+prefs(c).getString("report","")+"\n\nDiagnóstico: "+prefs(c).getString("lastDiagnostic","sin fallos registrados")+"\nEl código activo persiste al cerrar la app. Guardar un borrador no lo activa; ‘activa modulos’ prueba y activa. ‘revierte modulos’ recupera una revisión previa.";}
 static String repair(Context c,String request)throws Exception{String q=RuntimeProgram.normalize(request);Matcher kiss=Pattern.compile("^(.+?) (le de un besito|le da un besito|manda un beso|envia un beso|le mande un beso|le tire un beso|tira un beso|de un besito) a (.+)$").matcher(q);Matcher party=Pattern.compile("^(.+?) (festeja con|celebra junto a) (.+)$").matcher(q);JSONObject module;String pattern;
 if(kiss.matches()){pattern="{actor} "+kiss.group(2)+" a {target}";module=module("fix_beso_"+Integer.toHexString(pattern.hashCode()),pattern,new JSONArray().put(step("besa","actor","target")),new JSONArray().put("acercaactor").put("besa").put("recibebeso"));}
 else if(party.matches()){pattern="{actor} "+party.group(2)+" {target}";module=module("fix_fiesta_"+Integer.toHexString(pattern.hashCode()),pattern,example().getJSONArray("steps"),example().getJSONArray("tests").getJSONObject(0).getJSONArray("actions"));}
 else return "No tengo un reparador general para ese pedido. Puedo generar código de módulo para algunas formulaciones de beso o festejo usando acciones existentes. No cambié el código activo. Podés editar el módulo JSON para componer otras secuencias admitidas.";
 upsert(c,module);String report=activate(c);log(c,request,"Reparación de formulación: "+pattern+"; operaciones existentes, sin inventar una animación nueva.");return report+"\nCódigo generado: "+module.toString();}
 static BananaEngine.Result handle(Context c,String message)throws Exception{String q=ChatLanguage.normalize(message);
  if(q.equals("activa reparacion local")||q.equals("pausa reparacion local")){commit(prefs(c).edit().putBoolean("autoRepair",q.startsWith("activa")));return MobileCore.say(c,q.startsWith("activa")?"Activé la reparación automática de las formulaciones conocidas. Cada código generado se prueba antes de activarse.":"Pausé la generación automática de reparaciones. Los módulos ya activos se conservan.","modulos");}
  if(q.matches("estado de modulos|diagnostica modulos|estado del taller"))return MobileCore.say(c,status(c),"modulos");
  if(q.equals("ver codigo de modulos"))return MobileCore.say(c,"Código activo de comportamientos, revisión "+revision(c)+":\n"+new JSONObject(code(c)).toString(2),"modulos");
  if(q.equals("prepara ejemplo de modulo")){upsert(c,example());return MobileCore.say(c,"Preparé celebracion como borrador. Su código compone baile, saludo y salto. Podés editarlo o decir ‘activa modulos’.","modulos");}
  if(q.equals("prueba modulos"))return MobileCore.say(c,testCandidate(c),"modulos");
  if(q.equals("activa modulos"))return MobileCore.say(c,activate(c),"modulos");
  if(q.equals("revierte modulos"))return MobileCore.say(c,rollback(c),"modulos");
  if(q.equals("descarta codigo de modulos")){commit(prefs(c).edit().remove("candidate").remove("candidateBase").remove("candidateReport"));return MobileCore.say(c,"Descarté el borrador del taller. El código activo se conserva.","modulos");}
  if(q.startsWith("repara este pedido ")){int at=message.indexOf(':');String request=at>=0?message.substring(at+1).trim():message.substring("repara este pedido ".length()).trim();String report=repair(c,request);if(!report.startsWith("Revisión"))return MobileCore.say(c,report,"modulos");BananaEngine.Result result=execute(c,request);if(result==null)return MobileCore.say(c,report+"\nNo pude volver a interpretar el pedido; la escena se conserva.","modulos");result.text=report+"\n\n"+result.text;return result;}
  if(q.matches("(?s)^(?:planea|prepara un plan|aplica el plan|corrige paso|corregi paso|cambia paso|cuando diga|reformula mi pregunta|recorda|recuerda|busca|investiga|que|como|por que|quien|donde|cuanto|mis|ver mi plan)\\b.*")||MobilePlan.split(message).size()>1)return null;
  BananaEngine.Result current=execute(c,message);if(current!=null)return current;
  if(prefs(c).getBoolean("autoRepair",true)&&repairable(c,message)){try{String report=repair(c,message);BananaEngine.Result applied=execute(c,message);if(applied!=null){applied.text="Detecté una formulación que el motor base no cubría. Generé y probé una reparación local.\n"+report+"\n\n"+applied.text;return applied;}}catch(Exception failed){log(c,message,"Reparación automática no activada: "+failed.getMessage());return MobileCore.say(c,"No pude activar una reparación local: "+failed.getMessage()+". La escena se conserva.","modulos");}}
  return null;
 }
 static boolean repairable(Context c,String input)throws Exception{String q=RuntimeProgram.normalize(input);Matcher m=Pattern.compile("^(.+?) (?:le de un besito|le da un besito|de un besito) a (.+)$").matcher(q);if(!m.matches())m=Pattern.compile("^(.+?) (?:festeja con|celebra junto a) (.+)$").matcher(q);if(!m.matches())return false;SceneDraft d=MobileCore.scene(c);if(d==null)return false;SceneDraft.Actor a=RuntimeProgram.resolve(d,m.group(1)),b=RuntimeProgram.resolve(d,m.group(2));return a!=null&&b!=null&&a!=b;
 }

 static BananaEngine.Result execute(Context c,String message)throws Exception{String source=code(c);if(source.equals(EMPTY))return null;int version=revision(c);RuntimeProgram.Result result;SceneDraft base=MobileCore.scene(c);String snapshot=MobilePlan.snapshot(c);try{RuntimeProgram program=new RuntimeProgram(source);result=program.run(message,base);}catch(Exception unexpected){synchronized(RuntimeModules.class){if(revision(c)==version&&code(c).equals(source)){String restored;try{restored=recover(c);}catch(Exception failed){restored="No pude recuperar una revisión; el código no se ejecutó.";}log(c,message,"Fallo del módulo: "+unexpected.getMessage()+" · "+restored);return MobileCore.say(c,"El taller no pudo ejecutar este pedido. "+restored+"\nLa escena se conserva. Revisá ‘diagnostica modulos’.","modulos");}}return MobileCore.say(c,"Cambió la revisión mientras se comprobaba el pedido. Repetilo con la revisión actual.","modulos");}
  if(!result.matched)return null;if(result.scene==null){log(c,message,result.error);return MobileCore.say(c,"Módulo "+result.module+": "+result.error+"\nNo modifiqué la escena.","modulos");}
  synchronized(RuntimeModules.class){if(revision(c)!=version||!code(c).equals(source))return MobileCore.say(c,"El módulo cambió durante el pedido. Repetilo con la revisión actual.","modulos");synchronized(CreatorMemory.class){if(!snapshot.equals(MobilePlan.snapshot(c)))return MobileCore.say(c,"La escena cambió durante la comprobación; no apliqué el resultado viejo.","modulos");CreatorSession owner=CreatorMemory.load(c);String receipt=TaskReceipt.describe(base,result.scene,new String[]{"módulo "+result.module+" · revisión "+version});CreatorSession.Result update=owner.update(result.scene,owner.pending!=null,receipt,false);owner.lastTask=receipt;CreatorMemory.save(c,owner,update.commit);BananaEngine.Result out=MobileCore.say(c,"Ejecuté el código local "+result.module+" · revisión "+version+".\n"+receipt,"modulos");out.changed=update.commit!=null;if(out.draft)out.mode="borrador";MobileCore.record(c,message,"módulo "+result.module+" · revisión "+version,out,base);return out;}}
 }
}
